/**
 * @objective Generate default gate bootstrapping parameters with a given minimum security level
 * @param minimum_lambda Minimum security level (lambda) for the parameters
 * @return Pointer to newly allocated TFheGateBootstrappingParameterSet structure
 * 
 * @example
 * // Create parameters with 128-bit security
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * if (params != NULL) {
 *     // Generate keys using these parameters
 *     TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 *     // ... use the keys for encryption/computation ...
 *     delete_gate_bootstrapping_secret_keyset(secret_key);
 *     delete_gate_bootstrapping_parameters(params);
 * }
 */

/**
 * @objective Export the TFHE gate bootstrapping parameter set to a file
 * @param F File pointer where the parameters will be written
 * @param params Gate bootstrapping parameter set to export
 * @return void
 * 
 * @example
 * // Create parameters
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * 
 * // Export to file
 * FILE* file = fopen("my_params.tfhe", "wb");
 * if (file != NULL) {
 *     export_tfheGateBootstrappingParameterSet_toFile(file, params);
 *     fclose(file);
 * }
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Export the TFHE gate bootstrapping parameter set to an output stream
 * @param F Output stream where the parameters will be written
 * @param params Gate bootstrapping parameter set to export
 * @return void
 * 
 * @example
 * // Create parameters
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * 
 * // Export to output stream
 * std::ofstream file("my_params.tfhe", std::ios::binary);
 * if (file.is_open()) {
 *     export_tfheGateBootstrappingParameterSet_toStream(file, params);
 *     file.close();
 * }
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Read and construct a TFHE gate bootstrapping parameter set from a file
 * @param F File pointer to read the parameters from
 * @return Pointer to newly allocated TFheGateBootstrappingParameterSet structure
 * 
 * @example
 * // Read parameters from file
 * FILE* file = fopen("my_params.tfhe", "rb");
 * if (file != NULL) {
 *     TFheGateBootstrappingParameterSet* params = new_tfheGateBootstrappingParameterSet_fromFile(file);
 *     fclose(file);
 *     
 *     if (params != NULL) {
 *         // Use the loaded parameters
 *         TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 *         // ... perform operations ...
 *         delete_gate_bootstrapping_secret_keyset(secret_key);
 *         delete_gate_bootstrapping_parameters(params);
 *     }
 * }
 */

/**
 * @objective Read and construct a TFHE gate bootstrapping parameter set from a stream
 * @param F Input stream to read the parameters from
 * @return Pointer to newly allocated TFheGateBootstrappingParameterSet structure
 * 
 * @example
 * // Read parameters from input stream
 * std::ifstream file("my_params.tfhe", std::ios::binary);
 * if (file.is_open()) {
 *     TFheGateBootstrappingParameterSet* params = new_tfheGateBootstrappingParameterSet_fromStream(file);
 *     file.close();
 *     
 *     if (params != NULL) {
 *         // Use the loaded parameters
 *         TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 *         // ... perform operations ...
 *         delete_gate_bootstrapping_secret_keyset(secret_key);
 *         delete_gate_bootstrapping_parameters(params);
 *     }
 * }
 */

/**
 * @objective Delete and free a TFHE gate bootstrapping parameter set
 * @param params Gate bootstrapping parameter set to delete
 * @return void
 * 
 * @example
 * // Create and use parameters
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * // ... perform operations ...
 * 
 * // Cleanup: delete secret key first, then parameters
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Seed the TFHE random number generator with an array of values
 * @param values Array of seed values for the random generator
 * @param size Number of elements in the values array
 * @return void
 * 
 * @example
 * // Set random seed for reproducible results
 * uint32_t seed_values[] = {12345, 67890, 11111, 22222};
 * tfhe_random_generator_setSeed(seed_values, 4);
 * 
 * // Now generate parameters and keys with this seed
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * // The key generation will be deterministic with this seed
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Generate a new random TFHE gate bootstrapping secret key set
 * @param params Gate bootstrapping parameters used to generate the key set
 * @return Pointer to newly allocated TFheGateBootstrappingSecretKeySet structure
 * 
 * @example
 * // Create parameters first
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * 
 * // Generate random secret key set
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * if (secret_key != NULL) {
 *     // Extract cloud key for homomorphic operations
 *     const TFheGateBootstrappingCloudKeySet* cloud_key = &secret_key->cloud;
 *     
 *     // Use keys for encryption and computation
 *     // ...
 *     
 *     delete_gate_bootstrapping_secret_keyset(secret_key);
 * }
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Export the TFHE gate bootstrapping secret key set to a file
 * @param F File pointer where the secret key set will be written
 * @param keyset Secret key set to export
 * @return void
 * 
 * @example
 * // Generate secret key
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * // Export secret key to file
 * FILE* file = fopen("secret_key.tfhe", "wb");
 * if (file != NULL) {
 *     export_tfheGateBootstrappingSecretKeySet_toFile(file, secret_key);
 *     fclose(file);
 * }
 * 
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Export the TFHE gate bootstrapping secret key set to an output stream
 * @param F Output stream where the secret key set will be written
 * @param keyset Secret key set to export
 * @return void
 * 
 * @example
 * // Generate secret key
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * // Export secret key to output stream
 * std::ofstream file("secret_key.tfhe", std::ios::binary);
 * if (file.is_open()) {
 *     export_tfheGateBootstrappingSecretKeySet_toStream(file, secret_key);
 *     file.close();
 * }
 * 
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Read and construct a TFHE gate bootstrapping secret key set from a file
 * @param F File pointer to read the secret key set from
 * @return Pointer to newly allocated TFheGateBootstrappingSecretKeySet structure
 * 
 * @example
 * // Read secret key from file
 * FILE* file = fopen("secret_key.tfhe", "rb");
 * if (file != NULL) {
 *     TFheGateBootstrappingSecretKeySet* secret_key = new_tfheGateBootstrappingSecretKeySet_fromFile(file);
 *     fclose(file);
 *     
 *     if (secret_key != NULL) {
 *         // Use the loaded secret key for encryption/decryption
 *         LweSample* ciphertext = new_gate_bootstrapping_ciphertext(secret_key->params);
 *         bootsSymEncrypt(ciphertext, 1, secret_key);
 *         int result = bootsSymDecrypt(ciphertext, secret_key);
 *         
 *         delete_gate_bootstrapping_ciphertext(ciphertext);
 *         delete_gate_bootstrapping_secret_keyset(secret_key);
 *     }
 * }
 */

/**
 * @objective Read and construct a TFHE gate bootstrapping secret key set from a stream
 * @param F Input stream to read the secret key set from
 * @return Pointer to newly allocated TFheGateBootstrappingSecretKeySet structure
 * 
 * @example
 * // Read secret key from input stream
 * std::ifstream file("secret_key.tfhe", std::ios::binary);
 * if (file.is_open()) {
 *     TFheGateBootstrappingSecretKeySet* secret_key = new_tfheGateBootstrappingSecretKeySet_fromStream(file);
 *     file.close();
 *     
 *     if (secret_key != NULL) {
 *         // Use the loaded secret key
 *         LweSample* ciphertext = new_gate_bootstrapping_ciphertext(secret_key->params);
 *         bootsSymEncrypt(ciphertext, 0, secret_key);
 *         int result = bootsSymDecrypt(ciphertext, secret_key);
 *         
 *         delete_gate_bootstrapping_ciphertext(ciphertext);
 *         delete_gate_bootstrapping_secret_keyset(secret_key);
 *     }
 * }
 */

/**
 * @objective Delete and free a TFHE gate bootstrapping secret key set
 * @param keyset Secret key set to delete
 * @return void
 * 
 * @example
 * // Generate and use secret key
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * 
 * // Use the secret key for operations
 * LweSample* ciphertext = new_gate_bootstrapping_ciphertext(params);
 * bootsSymEncrypt(ciphertext, 1, secret_key);
 * int result = bootsSymDecrypt(ciphertext, secret_key);
 * 
 * // Cleanup
 * delete_gate_bootstrapping_ciphertext(ciphertext);
 * delete_gate_bootstrapping_secret_keyset(secret_key);  // Free secret key
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Export the TFHE gate bootstrapping cloud key set to a file
 * @param F File pointer where the cloud key set will be written
 * @param cloudKeyset Cloud key set to export
 * @return void
 * 
 * @example
 * // Generate keys
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * const TFheGateBootstrappingCloudKeySet* cloud_key = &secret_key->cloud;
 * 
 * // Export cloud key to file for server use
 * FILE* file = fopen("cloud_key.tfhe", "wb");
 * if (file != NULL) {
 *     export_tfheGateBootstrappingCloudKeySet_toFile(file, cloud_key);
 *     fclose(file);
 * }
 * 
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Export the TFHE gate bootstrapping cloud key set to an output stream
 * @param F Output stream where the cloud key set will be written
 * @param cloudKeyset Cloud key set to export
 * @return void
 * 
 * @example
 * // Generate keys
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * const TFheGateBootstrappingCloudKeySet* cloud_key = &secret_key->cloud;
 * 
 * // Export cloud key to output stream
 * std::ofstream file("cloud_key.tfhe", std::ios::binary);
 * if (file.is_open()) {
 *     export_tfheGateBootstrappingCloudKeySet_toStream(file, cloud_key);
 *     file.close();
 * }
 * 
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */

/**
 * @objective Perform bitwise AND gate operation
 * @param result Output ciphertext (a AND b)
 * @param ca First encrypted input
 * @param cb Second encrypted input
 * @param bk Cloud key for bootstrapping
 * @return void
 * 
 * @example
 * // Setup keys
 * TFheGateBootstrappingParameterSet* params = new_default_gate_bootstrapping_parameters(128);
 * TFheGateBootstrappingSecretKeySet* secret_key = new_random_gate_bootstrapping_secret_keyset(params);
 * const TFheGateBootstrappingCloudKeySet* cloud_key = &secret_key->cloud;
 * 
 * // Create ciphertexts
 * LweSample* bit_a = new_gate_bootstrapping_ciphertext(params);
 * LweSample* bit_b = new_gate_bootstrapping_ciphertext(params);
 * LweSample* result = new_gate_bootstrapping_ciphertext(params);
 * 
 * // Encrypt values: true AND false = false
 * bootsSymEncrypt(bit_a, 1, secret_key);
 * bootsSymEncrypt(bit_b, 0, secret_key);
 * 
 * // Perform AND operation
 * bootsAND(result, bit_a, bit_b, cloud_key);
 * 
 * // Decrypt result
 * int output = bootsSymDecrypt(result, secret_key);  // Should be 0
 * 
 * // Cleanup
 * delete_gate_bootstrapping_ciphertext(bit_a);
 * delete_gate_bootstrapping_ciphertext(bit_b);
 * delete_gate_bootstrapping_ciphertext(result);
 * delete_gate_bootstrapping_secret_keyset(secret_key);
 * delete_gate_bootstrapping_parameters(params);
 */
